{
  "name": "fair-play",
  "version": "1.0.0",
  "description": "Fair-play drop/loot engine: pseudo-random distribution (PRD) with pity caps, configurable pity timers, segment-adjusted weighted loot tables, and transparency reporting.",
  "type": "module",
  "main": "src/index.js",
  "exports": {
    ".": "./src/index.js"
  },
  "scripts": {
    "test": "node --test test/",
    "simulate": "node simulate.js"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

/**
 * Fair-play drop engine.
 *
 * Implements the four pillars of "fair play" loot design:
 *   1. PRD (pseudo-random distribution): the effective drop probability grows
 *      with every consecutive failure, so bad-luck streaks are front-loaded
 *      away and the long-run average matches the configured base rate.
 *   2. Configurable pity caps: a hard guarantee that bounds the worst-case
 *      streak (roll N is always a drop), plus periodic pity timers that
 *      reset progress on a calendar window (daily/weekly/monthly events).
 *   3. Weighted loot tables with segment-based dynamic adjustment
 *      (see src/loot-table.js).
 *   4. Transparency: players can always read their current streak, the
 *      effective chance of the next roll, and how many rolls remain until
 *      the guaranteed drop.
 *
 * Zero runtime dependencies; the RNG and the clock are injectable so tests
 * and simulations are fully deterministic.
 */

const DAY_MS = 86_400_000;
const WEEK_MS = 7 * DAY_MS;

/** @typedef {{baseRate?: number, increment?: number, pityCap?: number,
 *   periodicReset?: 'none'|'daily'|'weekly'|'monthly', resetHourUtc?: number,
 *   rng?: () => number, now?: () => number, historySize?: number}} EngineConfig */

function assertPositiveInt(name, value) {
  if (!Number.isInteger(value) || value < 1) {
    throw new RangeError(`${name} must be a positive integer, got ${value}`);
  }
}

/** Bucket a timestamp into the current pity window id. */
function windowId(periodicReset, resetHourUtc, nowMs) {
  if (periodicReset === 'none') return 'always';
  const shifted = new Date(nowMs + resetHourUtc * 3_600_000);
  if (periodicReset === 'daily') {
    return shifted.toISOString().slice(0, 10); // YYYY-MM-DD (UTC-shifted)
  }
  if (periodicReset === 'monthly') {
    return shifted.toISOString().slice(0, 7); // YYYY-MM
  }
  if (periodicReset === 'weekly') {
    // ISO week number of the shifted date.
    const d = new Date(Date.UTC(shifted.getUTCFullYear(), shifted.getUTCMonth(), shifted.getUTCDate()));
    const dayNum = (d.getUTCDay() + 6) % 7; // Mon = 0
    const thursday = new Date(d);
    thursday.setUTCDate(d.getUTCDate() - dayNum + 3);
    const isoYear = thursday.getUTCFullYear();
    const firstThursday = new Date(Date.UTC(isoYear, 0, 4));
    const firstDayNum = (firstThursday.getUTCDay() + 6) % 7;
    firstThursday.setUTCDate(firstThursday.getUTCDate() - firstDayNum + 3);
    const week = 1 + Math.round((thursday - firstThursday) / WEEK_MS);
    return `${isoYear}-W${String(week).padStart(2, '0')}`;
  }
  throw new RangeError(`Unsupported periodicReset: ${periodicReset}`);
}

export class FairPlayEngine {
  /**
   * @param {EngineConfig} [config]
   */
  constructor(config = {}) {
    this.config = {
      baseRate: 0.02,        // per-roll probability at streak 0
      increment: 0.005,      // PRD ramp: added per consecutive failure
      pityCap: 90,           // hard cap: the 90th consecutive failure drops for sure
      periodicReset: 'none', // 'none' | 'daily' | 'weekly' | 'monthly'
      resetHourUtc: 0,       // hour (UTC) at which a new pity window starts
      rng: Math.random,
      now: () => Date.now(),
      historySize: 50,
      ...config,
    };
    const { baseRate, increment, pityCap, periodicReset, rng, now } = this.config;
    if (!(baseRate > 0 && baseRate < 1)) {
      throw new RangeError(`baseRate must be in (0, 1), got ${baseRate}`);
    }
    if (!(increment >= 0 && increment < 1)) {
      throw new RangeError(`increment must be in [0, 1), got ${increment}`);
    }
    assertPositiveInt('pityCap', pityCap);
    if (typeof rng !== 'function' || typeof now !== 'function') {
      throw new TypeError('rng and now must be functions');
    }
    const w = this.currentWindowId();
    this.state = {
      streak: 0,             // consecutive failures since the last drop
      windowId: w,           // pity window the streak belongs to
      lastDropAt: null,      // epoch ms of the last drop (null = no drop yet)
      totalRolls: 0,
      totalDrops: 0,
      resetsFromWindow: 0,   // how often a new window wiped a streak (transparency)
      history: [],           // recent drops: { roll, at, streakBefore }
    };
  }

  /** @returns {string} the current pity-window id. */
  currentWindowId() {
    return windowId(this.config.periodicReset, this.config.resetHourUtc, this.config.now());
  }

  /**
   * Effective chance of a drop for a given number of consecutive failures,
   * before the pity guarantee kicks in. Monotonically non-decreasing in s.
   * @param {number} streak consecutive failures so far
   * @returns {number} probability in [0, 1]
   */
  effectiveChanceAt(streak) {
    if (streak >= this.config.pityCap - 1) return 1;
    return Math.min(this.config.baseRate + this.config.increment * streak, 1);
  }

  /**
   * Expected long-run drop rate (drops per roll) for the configured PRD + pity,
   * derived analytically from the renewal process: E[rolls per drop] =
   * sum over n of P(T >= n). Used to validate simulations and to show players
   * the "true" rate the PRD is calibrated to.
   */
  theoreticalRate() {
    const { pityCap } = this.config;
    let survival = 1; // P(no drop in the first 0 rolls)
    let expectation = 0;
    for (let n = 1; n <= pityCap; n++) {
      expectation += survival; // P(T >= n)
      const p = this.effectiveChanceAt(n - 1);
      survival *= 1 - p;
      if (survival === 0) break;
    }
    return 1 / expectation;
  }

  /**
   * Roll once. Returns true when the drop happens.
   * @returns {boolean}
   */
  roll() {
    const { periodicReset, pityCap, rng, now } = this.config;
    const s = this.state.streak;

    // Pity timer: if the streak belongs to a previous calendar window, the
    // window closed without a drop — progress expires (documented behavior).
    if (periodicReset !== 'none') {
      const w = this.currentWindowId();
      if (w !== this.state.windowId) {
        this.state.streak = 0;
        this.state.windowId = w;
        this.state.resetsFromWindow += 1;
      }
    }

    const nextStreak = this.state.streak;
    let dropped = false;
    if (nextStreak >= pityCap - 1) {
      dropped = true; // hard pity guarantee
    } else {
      dropped = rng() < this.effectiveChanceAt(nextStreak);
    }

    this.state.totalRolls += 1;
    if (dropped) {
      const at = now();
      this.state.history.push({
        roll: this.state.totalRolls,
        at,
        streakBefore: nextStreak,
      });
      if (this.state.history.length > this.config.historySize) {
        this.state.history.shift();
      }
      this.state.streak = 0;
      this.state.totalDrops += 1;
      this.state.lastDropAt = at;
    } else {
      this.state.streak = nextStreak + 1;
    }
    return dropped;
  }

  /**
   * Transparency snapshot for UI / logs. Shows players exactly where their
   * bad-luck protection stands.
   */
  report() {
    const s = this.state.streak;
    const effectiveChance = this.effectiveChanceAt(s);
    return {
      streak: s,
      effectiveChance,
      guaranteedNext: effectiveChance === 1,
      rollsToGuarantee: Math.max(0, this.config.pityCap - s),
      pityCap: this.config.pityCap,
      pityWindow: this.config.periodicReset,
      windowId: this.state.windowId,
      resetsFromWindow: this.state.resetsFromWindow,
      totalRolls: this.state.totalRolls,
      totalDrops: this.state.totalDrops,
      observedRate: this.state.totalRolls
        ? this.state.totalDrops / this.state.totalRolls
        : null,
      theoreticalRate: this.theoreticalRate(),
      lastDropAt: this.state.lastDropAt,
      recentDrops: this.state.history.slice(-5),
    };
  }

  /** Serializable state (for persistence across sessions/reboots). */
  toJSON() {
    return {
      config: { ...this.config, rng: undefined, now: undefined },
      state: this.state,
    };
  }

  /**
   * Restore state from toJSON(). The stored config (minus the injectables) is
   * reused unless overrides are passed.
   * @param {object} json
   * @param {EngineConfig} [overrides]
   */
  static fromJSON(json, overrides = {}) {
    const engine = new FairPlayEngine({ ...json.config, ...overrides });
    const w = engine.currentWindowId();
    engine.state = {
      ...json.state,
      windowId: w, // always re-anchor to the current window on restore
      history: Array.isArray(json.state?.history) ? json.state.history : [],
    };
    return engine;
  }
}

/**
 * Weighted loot table with segment-based dynamic adjustment.
 *
 * - Static weights: each entry has a base weight; the relative share of each
 *   entry is weight / sum(weights) (entries filtered by segment eligibility).
 * - Segment adjustment: player segments (e.g. "new", "returning", "veteran")
 *   can multiply entry weights. Multipliers are bounded to keep the economy
 *   stable, and every adjustment is fully visible to players via
 *   `adjustedWeights()` — no hidden skew.
 *
 * Fair-play guardrails enforced here:
 *   * segment multipliers are clamped to a configurable range (default 0.5x–2x);
 *   * the adjusted table always re-normalizes, so all rows sum to 1;
 *   * per-segment expected rates are computable and exportable, so game-design
 *     can audit that no segment is exploited.
 */

/** @typedef {{id: string, weight: number, label?: string,
 *   minSegment?: string, maxSegment?: string}} TableEntry */

const DEFAULT_MULTIPLIER_BOUNDS = { min: 0.5, max: 2 };

function normalizeEntry(entry) {
  if (!entry || typeof entry.id !== 'string' || entry.id.length === 0) {
    throw new TypeError('each entry needs a non-empty string id');
  }
  if (!(entry.weight > 0) || !Number.isFinite(entry.weight)) {
    throw new RangeError(`entry "${entry.id}" weight must be a positive finite number`);
  }
  return { label: entry.id, ...entry };
}

export class WeightedLootTable {
  /**
   * @param {object} params
   * @param {TableEntry[]} params.entries
   * @param {Record<string, Record<string, number>>} [params.segmentMultipliers]
   *   e.g. { new: { sword: 1.5 } } — extra multiplier for entry "sword" for
   *   segment "new". Missing entries default to 1.
   * @param {{min: number, max: number}} [params.multiplierBounds]
   */
  constructor({ entries, segmentMultipliers = {}, multiplierBounds = DEFAULT_MULTIPLIER_BOUNDS }) {
    if (!Array.isArray(entries) || entries.length === 0) {
      throw new RangeError('entries must be a non-empty array');
    }
    this.entries = entries.map(normalizeEntry);
    this.multiplierBounds = multiplierBounds;
    this.segmentMultipliers = segmentMultipliers;
  }

  /**
   * Convenience constructor from a plain { id: weight } map.
   * @param {Record<string, number>} weights
   */
  static fromWeights(weights) {
    return new WeightedLootTable({
      entries: Object.entries(weights).map(([id, weight]) => ({ id, weight })),
    });
  }

  /**
   * Effective weights for a segment after eligibility filter + multipliers.
   * @param {string} [segment='default']
   * @returns {Array<{id: string, label: string, weight: number}>}
   */
  effectiveEntries(segment = 'default') {
    const bounds = this.multiplierBounds;
    const seg = this.segmentMultipliers[segment] ?? {};
    const out = [];
    for (const e of this.entries) {
      if (e.minSegment && segment < e.minSegment) continue;
      if (e.maxSegment && segment > e.maxSegment) continue;
      let weight = e.weight;
      const mult = seg[e.id];
      if (mult !== undefined) {
        if (!Number.isFinite(mult) || mult <= 0) {
          throw new RangeError(`segment multiplier for "${e.id}" must be a positive finite number`);
        }
        weight *= Math.min(Math.max(mult, bounds.min), bounds.max);
      }
      out.push({ id: e.id, label: e.label, weight });
    }
    return out;
  }

  /**
   * Chances after adjustment for a segment (sums to 1). This is the
   * transparency view: what the player is actually rolling against.
   * @param {string} [segment]
   * @returns {Array<{id: string, label: string, weight: number, chance: number}>}
   */
  adjustedWeights(segment = 'default') {
    const effective = this.effectiveEntries(segment);
    const total = effective.reduce((sum, e) => sum + e.weight, 0);
    return effective.map((e) => ({ ...e, chance: e.weight / total }));
  }

  /**
   * Pick one entry by weighted random draw.
   * @param {string} [segment]
   * @param {() => number} [rng]
   * @returns {{id: string, label: string, chance: number}}
   */
  roll(segment = 'default', rng = Math.random) {
    const rows = this.adjustedWeights(segment);
    const u = rng() * rows.reduce((sum, r) => sum + r.weight, 0);
    let acc = 0;
    for (const r of rows) {
      acc += r.weight;
      if (u < acc) return r;
    }
    return rows[rows.length - 1]; // float-safety fallback
  }
}

/**
 * fair-play — drop/loot engine with PRD, pity caps, pity timers,
 * segment-adjusted weighted tables, and transparency reporting.
 */

export { FairPlayEngine } from './fair-play.js';
export { WeightedLootTable } from './loot-table.js';

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { FairPlayEngine, WeightedLootTable } from '../src/index.js';

/** RNG stub that always fails (returns ~1), for forcing bad luck. */
const alwaysFail = () => 0.9999999;
/** RNG stub that always succeeds (returns ~0). */
const alwaysWin = () => 0.0000001;
/** Deterministic LCG for reproducible distributions. */
function lcg(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function makeClock() {
  let t = 1_700_000_000_000;
  return {
    now: () => t,
    advance: (ms) => { t += ms; },
  };
}

test('PRD: effective chance grows monotonically with consecutive failures', () => {
  const e = new FairPlayEngine({ baseRate: 0.02, increment: 0.01, pityCap: 90, rng: alwaysFail });
  let prev = 0;
  for (let s = 0; s < 80; s++) {
    const p = e.effectiveChanceAt(s);
    assert.ok(p >= prev, `chance must not decrease at streak ${s}`);
    prev = p;
  }
  assert.equal(e.effectiveChanceAt(0), 0.02);
  assert.equal(e.effectiveChanceAt(1), 0.03);
});

test('pity guarantee: the cap-th consecutive failure is a guaranteed drop', () => {
  const e = new FairPlayEngine({ baseRate: 0.01, increment: 0.001, pityCap: 50, rng: alwaysFail });
  let drops = 0;
  for (let roll = 1; roll <= 50; roll++) {
    const dropped = e.roll();
    if (roll < 50) {
      assert.equal(dropped, false, `roll ${roll} should fail before the cap`);
    } else {
      assert.equal(dropped, true, `roll 50 must be guaranteed`);
      drops++;
    }
  }
  assert.equal(drops, 1);
  // Streak resets after the pity drop.
  assert.equal(e.report().streak, 0);
});

test('streak resets on a normal drop, totals accumulate', () => {
  const e = new FairPlayEngine({ baseRate: 0.5, increment: 0, pityCap: 10, rng: alwaysWin });
  assert.equal(e.roll(), true);
  assert.equal(e.roll(), true);
  const r = e.report();
  assert.equal(r.totalRolls, 2);
  assert.equal(r.totalDrops, 2);
  assert.equal(r.streak, 0);
});

test('worst streak never exceeds pityCap - 1 across a long adversarial run', () => {
  const e = new FairPlayEngine({ baseRate: 0.005, increment: 0.0005, pityCap: 40, rng: lcg(7) });
  let maxStreak = 0;
  for (let i = 0; i < 200_000; i++) {
    e.roll();
    maxStreak = Math.max(maxStreak, e.report().streak);
  }
  assert.ok(maxStreak <= 39, `max streak ${maxStreak} must not exceed pityCap - 1 = 39`);
});

test('long-run observed rate converges to the analytic theoretical rate', () => {
  const e = new FairPlayEngine({ baseRate: 0.02, increment: 0.005, pityCap: 90, rng: lcg(42) });
  const rolls = 500_000;
  for (let i = 0; i < rolls; i++) e.roll();
  const r = e.report();
  assert.ok(r.theoreticalRate > 0.02, 'PRD must raise the true rate above the base rate');
  assert.ok(
    Math.abs(r.observedRate - r.theoreticalRate) < 0.0015,
    `observed ${r.observedRate.toFixed(5)} vs theoretical ${r.theoreticalRate.toFixed(5)}`
  );
});

test('transparency report exposes streak, chance, and rolls-to-guarantee', () => {
  const e = new FairPlayEngine({ baseRate: 0.05, increment: 0.02, pityCap: 20, rng: alwaysFail });
  e.roll(); e.roll();
  const r = e.report();
  assert.equal(r.streak, 2);
  assert.equal(r.effectiveChance, 0.05 + 0.02 * 2);
  assert.equal(r.rollsToGuarantee, 20 - 2);
  assert.equal(r.guaranteedNext, false);
  assert.ok(Number.isFinite(r.theoreticalRate));
});

test('pity timer (daily): streak expires when the calendar window flips', () => {
  const clock = makeClock();
  const e = new FairPlayEngine({
    baseRate: 0.02, increment: 0.01, pityCap: 90,
    periodicReset: 'daily', resetHourUtc: 0, rng: alwaysFail, now: clock.now,
  });
  // 2023-11-14T21:33:20Z — one day later crosses into 2023-11-15 UTC.
  for (let i = 0; i < 5; i++) e.roll();
  assert.equal(e.report().streak, 5);
  clock.advance(86_400_000);
  e.roll(); // triggers the window check
  const r = e.report();
  assert.equal(r.streak, 1, 'streak must reset when the window flips');
  assert.equal(r.resetsFromWindow, 1);
  assert.equal(r.totalRolls, 6, 'totals must survive the window flip');
});

test('weekly window id is ISO-week based and stable across days in the same week', () => {
  const e = new FairPlayEngine({ baseRate: 0.1, increment: 0, pityCap: 5, periodicReset: 'weekly' });
  // 2024-01-01 is a Monday → ISO week 2024-W01; +3 days stays in W01.
  const c1 = { ...e, state: { ...e.state } };
  assert.equal(c1.currentWindowId(), '2024-W01');
  const clock = makeClock();
  const tuesday = clock.now() + 86_400_000;
  assert.equal(FairPlayEngine.prototype.currentWindowId.call({ config: { periodicReset: 'weekly', resetHourUtc: 0, now: () => tuesday } }), '2024-W01');
});

test('pity timer (monthly) resets across months but not within a month', () => {
  const clock = makeClock();
  const e = new FairPlayEngine({
    baseRate: 0.05, increment: 0, pityCap: 50,
    periodicReset: 'monthly', rng: alwaysFail, now: clock.now,
  });
  e.roll();
  clock.advance(30 * 86_400_000); // +30d stays within November 2023
  e.roll();
  assert.equal(e.report().streak, 2, 'no reset within the same month');
  clock.advance(20 * 86_400_000); // now December
  e.roll();
  assert.equal(e.report().streak, 1, 'reset after month flip');
});

test('persistence: toJSON/fromJSON round-trips streak and totals, re-anchors window', () => {
  const clock = makeClock();
  const e = new FairPlayEngine({ baseRate: 0.02, increment: 0.01, pityCap: 90, rng: alwaysFail, now: clock.now });
  e.roll(); e.roll(); e.roll();
  const json = e.toJSON();
  const restored = FairPlayEngine.fromJSON(json, { rng: alwaysFail, now: clock.now });
  const r = restored.report();
  assert.equal(r.streak, 3);
  assert.equal(r.totalRolls, 3);
  assert.equal(r.windowId, e.report().windowId);
});

// ---------------- Weighted loot table ----------------

test('loot table: static weights normalize to 1 and respect relative shares', () => {
  const t = WeightedLootTable.fromWeights({ common: 70, rare: 25, epic: 4, legendary: 1 });
  const rows = t.adjustedWeights();
  const total = rows.reduce((s, r) => s + r.chance, 0);
  assert.ok(Math.abs(total - 1) < 1e-12);
  const legendary = rows.find((r) => r.id === 'legendary');
  assert.equal(legendary.chance, 0.01);
});

test('loot table: weighted draws match expected shares within tolerance', () => {
  const t = WeightedLootTable.fromWeights({ a: 60, b: 30, c: 10 });
  const counts = { a: 0, b: 0, c: 0 };
  const rng = lcg(1234);
  const N = 60_000;
  for (let i = 0; i < N; i++) counts[t.roll('default', rng).id]++;
  assert.ok(Math.abs(counts.a / N - 0.6) < 0.01, `a=${counts.a / N}`);
  assert.ok(Math.abs(counts.b / N - 0.3) < 0.01, `b=${counts.b / N}`);
  assert.ok(Math.abs(counts.c / N - 0.1) < 0.01, `c=${counts.c / N}`);
});

test('segment adjustment: multipliers shift shares, rows still sum to 1, bounds enforced', () => {
  const t = new WeightedLootTable({
    entries: [{ id: 'common', weight: 100 }, { id: 'rare', weight: 10 }, { id: 'epic', weight: 1 }],
    segmentMultipliers: { new: { epic: 50, rare: 5 } }, // way out of bounds on purpose
    multiplierBounds: { min: 0.5, max: 2 },
  });
  const base = t.adjustedWeights('default');
  const boosted = t.adjustedWeights('new');
  const epicBase = base.find((r) => r.id === 'epic').chance;
  const epicNew = boosted.find((r) => r.id === 'epic').chance;
  // multiplier 50 clamps to max 2 → epic chance at most doubles the base chance
  assert.ok(epicNew <= epicBase * 2.0001, `epicNew=${epicNew} epicBase=${epicBase}`);
  assert.ok(epicNew > epicBase, 'boosted epic must still be more likely than default');
  assert.ok(Math.abs(boosted.reduce((s, r) => s + r.chance, 0) - 1) < 1e-12);
});

test('segment adjustment: eligibility ranges filter entries per segment', () => {
  const t = new WeightedLootTable({
    entries: [
      { id: 'starter-potion', weight: 1, maxSegment: 'new' },
      { id: 'endgame-gem', weight: 1, minSegment: 'veteran' },
      { id: 'common-drop', weight: 1 },
    ],
  });
  const ids = (seg) => t.adjustedWeights(seg).map((r) => r.id);
  assert.deepEqual(ids('new'), ['starter-potion', 'common-drop']);
  assert.deepEqual(ids('regular'), ['common-drop']);
  assert.deepEqual(ids('veteran'), ['endgame-gem', 'common-drop']);
});

test('segment adjustment: draws follow the adjusted distribution', () => {
  const t = new WeightedLootTable({
    entries: [{ id: 'a', weight: 1 }, { id: 'b', weight: 1 }],
    segmentMultipliers: { vip: { a: 3 } },
  });
  const counts = { a: 0, b: 0 };
  const rng = lcg(99);
  const N = 20_000;
  for (let i = 0; i < N; i++) counts[t.roll('vip', rng).id]++;
  assert.ok(Math.abs(counts.a / N - 0.75) < 0.02, `a=${counts.a / N}`);
});

test('validation: bad entries and multipliers throw', () => {
  assert.throws(() => WeightedLootTable.fromWeights({ x: 0 }), /positive finite/);
  assert.throws(() => new WeightedLootTable({ entries: [{ id: '', weight: 1 }] }), /non-empty string id/);
  const t = WeightedLootTable.fromWeights({ a: 1, b: 1 });
  assert.throws(() => t.adjustedWeights('bad'), /must be a positive finite number/);
});

test('engine validation: invalid config throws', () => {
  assert.throws(() => new FairPlayEngine({ baseRate: 0 }), /baseRate/);
  assert.throws(() => new FairPlayEngine({ baseRate: 1 }), /baseRate/);
  assert.throws(() => new FairPlayEngine({ baseRate: 0.1, increment: 2 }), /increment/);
  assert.throws(() => new FairPlayEngine({ baseRate: 0.1, pityCap: 0 }), /pityCap/);
});

