/**
 * Fairness simulation: runs many synthetic players through the engine and
 * prints a report that verifies the four fair-play pillars empirically.
 *
 *   node simulate.js
 */

import { FairPlayEngine, WeightedLootTable } from './src/index.js';

function lcg(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

const PLAYERS = 50_000;
const ROLLS_PER_PLAYER = 200;
const CONFIG = { baseRate: 0.02, increment: 0.005, pityCap: 90 };
const TABLE = new WeightedLootTable({
  entries: [
    { id: 'common', weight: 68, label: 'Common' },
    { id: 'rare', weight: 22, label: 'Rare' },
    { id: 'epic', weight: 8, label: 'Epic' },
    { id: 'legendary', weight: 2, label: 'Legendary' },
  ],
  segmentMultipliers: {
    new: { epic: 1.5, legendary: 1.5 }, // onboarding boost for newcomers
  },
});

const players = Array.from({ length: PLAYERS }, (_, i) => {
  const engine = new FairPlayEngine({ ...CONFIG, rng: lcg(i + 1) });
  const drops = { common: 0, rare: 0, epic: 0, legendary: 0 };
  let maxStreak = 0;
  for (let r = 0; r < ROLLS_PER_PLAYER; r++) {
    if (engine.roll()) {
      drops[TABLE.roll('default', engine.config.rng).id]++;
    }
    maxStreak = Math.max(maxStreak, engine.report().streak);
  }
  const rep = engine.report();
  return {
    drops: Object.values(drops).reduce((a, b) => a + b, 0),
    byTier: drops,
    maxStreak,
    observedRate: rep.observedRate,
  };
});

const totalRolls = PLAYERS * ROLLS_PER_PLAYER;
const totalDrops = players.reduce((s, p) => s + p.drops, 0);
const observed = totalDrops / totalRolls;
const engine0 = new FairPlayEngine(CONFIG);
const theoretical = engine0.theoreticalRate();

const maxStreakGlobal = Math.max(...players.map((p) => p.maxStreak));
const worstPlayer = players.reduce((a, b) => (b.drops < a.drops ? b : a));

// Gini coefficient over drops-per-player — 0 = perfectly fair.
const sorted = players.map((p) => p.drops).sort((a, b) => a - b);
const n = sorted.length;
let giniNum = 0;
for (let i = 0; i < n; i++) giniNum += (2 * i - n + 1) * sorted[i];
const gini = giniNum / (n * sorted.reduce((s, x) => s + x, 0));

const fmt = (x) => x.toFixed(4);
const line = '─'.repeat(62);

console.log(`\n${line}`);
console.log('FAIR-PLAY DROP ENGINE — SIMULATION REPORT');
console.log(line);
console.log(`players × rolls        : ${PLAYERS.toLocaleString()} × ${ROLLS_PER_PLAYER}`);
console.log(`config                 : base=${CONFIG.baseRate} increment=${CONFIG.increment} pityCap=${CONFIG.pityCap}`);
console.log(`theoretical rate       : ${fmt(theoretical)}  (analytic renewal expectation)`);
console.log(`observed rate          : ${fmt(observed)}`);
console.log(`deviation              : ${(observed - theoretical).toFixed(5)}`);
console.log(`${line}`);
console.log('BAD-LUCK BOUNDS');
console.log(`worst streak (global)  : ${maxStreakGlobal}  (pityCap ${CONFIG.pityCap} ⇒ guaranteed at ${CONFIG.pityCap - 1} failures)`);
console.log(`worst player drops     : ${worstPlayer.drops}/${ROLLS_PER_PLAYER}  (rate ${fmt(worstPlayer.observedRate)})`);
console.log(`${line}`);
console.log('FAIRNESS (drops per player)');
console.log(`mean drops/player      : ${fmt(players.reduce((s, p) => s + p.drops, 0) / PLAYERS)}`);
console.log(`gini coefficient       : ${fmt(gini)}   (0 = perfectly even distribution)`);
console.log(`${line}`);
console.log('LOOT TABLE (share of dropped items, expected vs observed)');
const totalByTier = { common: 0, rare: 0, epic: 0, legendary: 0 };
for (const p of players) for (const k of Object.keys(totalByTier)) totalByTier[k] += p.byTier[k];
for (const row of TABLE.adjustedWeights('default')) {
  const obs = totalByTier[row.id] / totalDrops;
  console.log(
    `  ${row.id.padEnd(10)} expected ${fmt(row.chance).padStart(6)}   observed ${fmt(obs).padStart(6)}`
  );
}
console.log(line);
console.log('TRANSPARENCY SAMPLE (player-facing progress view)');
const sample = new FairPlayEngine({ ...CONFIG, rng: lcg(999) });
for (let i = 0; i < 57; i++) sample.roll();
const r = sample.report();
console.log(`  streak            : ${r.streak}`);
console.log(`  next-roll chance  : ${fmt(r.effectiveChance)}`);
console.log(`  rolls-to-guarantee: ${r.rollsToGuarantee}`);
console.log(`  guaranteed next   : ${r.guaranteedNext}`);
console.log(`${line}\n`);

